import heapq


def _build_jobs(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        eligible = [job for job in jobs if job["id"] not in blocked]
        best_value = None
        best_ids = None

        for chosen in combinations(eligible, k):
            ids = [job["id"] for job in chosen]
            id_set = set(ids)
            if not mandatory.issubset(id_set):
                continue
            counts = {}
            for job in chosen:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            active = []
            valid = True
            for job in sorted(chosen, key=lambda j: (j["start"], j["end"])):
                while active and active[0] <= job["start"]:
                    heapq.heappop(active)
                heapq.heappush(active, job["end"])
                if len(active) > capacity:
                    valid = False
                    break
            if not valid:
                continue

            selected = sorted(ids)
            value = sum(job["value"] for job in chosen)
            if (best_value is None or value > best_value or
                    (value == best_value and
                     ((tie == "smallest" and selected < best_ids) or
                      (tie == "largest" and selected > best_ids)))):
                best_value, best_ids = value, selected

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (sequence, event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            tax = rounded(net * event.get("tax_bp", 0), 10000, mode)
            amount = net + tax
            if event.get("kind") == "refund":
                amount = -amount
            account = event.get("account", "default")
            currency = event.get("currency", "USD")
            key = account + "|" + currency
            balances[key] = balances.get(key, 0) + amount
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        rows = {name: {row["version"]: row for row in versions}
                for name, versions in packages.items()}

        choices = []
        for name in names:
            versions = sorted(rows[name], reverse=True)
            choices.append(versions + [-1])

        best_vector = None
        best_versions = None
        for assignment in product(*choices):
            selected = dict(zip(names, assignment))
            required = {}
            graph = {}
            pending = []
            for name, (low, high) in data["roots"].items():
                pending.append((name, low, high))

            valid = True
            while pending and valid:
                name, low, high = pending.pop()
                version = selected[name]
                if (version == -1 or not low <= version <= high or
                        version in blocked.get(name, []) or
                        (name in pins and version != pins[name])):
                    valid = False
                    break
                if name in required:
                    required[name].append((low, high))
                    continue
                required[name] = [(low, high)]
                row = rows[name][version]
                active_deps = [dep for dep in row.get("deps", [])
                               if not dep.get("feature") or dep["feature"] in features]
                graph[name] = [dep["name"] for dep in active_deps]
                pending.extend((dep["name"], dep["min"], dep["max"])
                               for dep in active_deps)

            if not valid or set(name for name, v in selected.items() if v != -1) != set(required):
                continue
            if any(not low <= selected[name] <= high
                   for name, ranges in required.items() for low, high in ranges):
                continue

            finished, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(dep) for dep in graph.get(name, [])):
                    return False
                active.remove(name)
                finished.add(name)
                return True

            if not all(visit(name) for name in graph):
                continue
            vector = tuple(selected[name] for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = {name: selected[name] for name in names
                                 if selected[name] != -1}

        if best_vector is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        required_bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        source = data["source"]
        start_mask = required_bit.get(source, 0)
        start_state = (source, start_mask, 0)
        dist = {start_state: data["start"]}
        queue = [(data["start"], source, start_mask, 0)]
        coupons = data["coupons"]
        deadline = data["deadline"]

        while queue:
            time, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if dist.get(state) != time:
                continue
            if node == data["target"] and mask == full and used == coupons:
                return {"arrival": time}

            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], used)]
                if used < coupons:
                    options.append((max(2, edge["duration"] - edge.get("discount", 0)), used + 1))
                for duration, next_used in options:
                    arrival = depart + duration
                    if arrival > deadline:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | required_bit.get(next_node, 0)
                    next_state = (next_node, next_mask, next_used)
                    if arrival < dist.get(next_state, float("inf")):
                        dist[next_state] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_mask, next_used))
        return {"arrival": None}
    return solve


